def organize_weekly_activities(basketball_player_activities, animal_enthusiast_activities):
    combined_activities = {}

    # Combine activities from both dictionaries
    for day, activities in basketball_player_activities.items():
        combined_activities.setdefault(day, []).extend(activities)

    for day, activities in animal_enthusiast_activities.items():
        combined_activities.setdefault(day, []).extend(activities)

    # Remove duplicates and sort activities for each day
    for day, activities in combined_activities.items():
        combined_activities[day] = sorted(set(activities))

    return combined_activities

def calculate_win_rate(matches):
    wins = matches.count("win")
    total_matches = len(matches)
    win_rate = (wins / total_matches) * 100
    return round(win_rate, 2)

def analyze_cultural_themes(descriptions):
    theme_counts = {}
    for description in descriptions:
        description = description.lower()
        words = description.split()
        for i in range(len(words) - 1):
            theme = words[i] + " " + words[i+1]
            if theme in theme_counts:
                theme_counts[theme] += 1
            else:
                theme_counts[theme] = 1
    return theme_counts

def categorize_facts(facts):
    result = {}
    for fact in facts:
        animal, detail = fact.split(": ", 1)
        if animal in result:
            result[animal].append(detail)
        else:
            result[animal] = [detail]
    return result

def get_family_names(full_names):
    family_names = set()
    for name in full_names:
        family_name = name.split()[0]
        family_names.add(family_name)
    return sorted(list(family_names))

def convert_to_range_string(num_list):
    ranges = []
    start = num_list[0]
    end = start

    for i in range(1, len(num_list)):
        if num_list[i] == end + 1:
            end = num_list[i]
        else:
            if start == end:
                ranges.append(str(start))
            else:
                ranges.append(f"{start}-{end}")
            start = num_list[i]
            end = start

    if start == end:
        ranges.append(str(start))
    else:
        ranges.append(f"{start}-{end}")

    return ",".join(ranges)

def create_property_class(class_name, attribute_name, initial_value):
    def getter(self):
        return getattr(self, '_' + attribute_name)

    def setter(self, value):
        setattr(self, '_' + attribute_name, value)

    prop = property(getter, setter)

    cls = type(class_name, (object,), {
        '__init__': lambda self: setattr(self, '_' + attribute_name, initial_value),
        attribute_name: prop
    })

    return cls

def find_top_customer(customer_interactions):
    if not customer_interactions:
        return None

    max_interactions = max(count for _, count in customer_interactions)
    for name, count in customer_interactions:
        if count == max_interactions:
            return name

def calculate_tour_cost(days, accommodation, people):
    cost_per_day = {
        "standard": 50,
        "deluxe": 100,
        "luxury": 200
    }
    total_cost = days * cost_per_day[accommodation] * people
    return total_cost
